const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const center = ee.Geometry.Point([140.468626, -45.432798]);
    const geom = center.buffer(100000); // 100 km
    const scale = 4000;

    const periods = [
      { label: '2018-11 to 2019-02', start: '2018-11-01', end: '2019-03-01' },
      { label: '2019-11 to 2020-02', start: '2019-11-01', end: '2020-03-01' }
    ];

    const datasets = [
      'NASA/OBPG/MODISA/L3SMI',
      'NASA/OBPG/MODIST/L3SMI',
      'NASA/OBPG/VIIRS_SNPP/L3SMI'
    ];

    function getInfo(eeObj) {
      return new Promise((resolve, reject) => eeObj.getInfo(resolve, reject));
    }

    async function getPeriodStats(startStr, endStr) {
      let chosen = null;
      let size = 0;
      let col = null;

      for (const ds of datasets) {
        col = ee.ImageCollection(ds)
          .filterDate(startStr, endStr)
          .filterBounds(geom)
          .select('chlor_a');
        size = await getInfo(col.size());
        if (size > 0) { chosen = ds; break; }
      }

      if (!chosen) {
        // small recovery: widen by ±15 days if still empty
        const start2 = ee.Date(startStr).advance(-15, 'day');
        const end2 = ee.Date(endStr).advance(15, 'day');
        for (const ds of datasets) {
          col = ee.ImageCollection(ds)
            .filterDate(start2, end2)
            .filterBounds(geom)
            .select('chlor_a');
          size = await getInfo(col.size());
          if (size > 0) { chosen = ds; break; }
        }
        // If we only found images in widened window, still proceed using the original dates if possible
        if (!chosen) return { status: 'C1' };
        // Rebuild collection with original dates for fairness; if 0, use widened as last resort
        let colOrig = ee.ImageCollection(chosen).filterDate(startStr, endStr).filterBounds(geom).select('chlor_a');
        const sizeOrig = await getInfo(colOrig.size());
        if (sizeOrig > 0) { col = colOrig; size = sizeOrig; }
      }

      const meanImg = ee.ImageCollection(col).mean();

      const totalCount = await getInfo(
        ee.Image(1).rename('one').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geom,
          scale: scale,
          maxPixels: 1e9
        }).get('one')
      );

      const validCount = await getInfo(
        meanImg.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geom,
          scale: scale,
          maxPixels: 1e9
        }).get('chlor_a')
      );

      if (!totalCount || totalCount === 0) {
        return { status: 'C2', dataset: chosen, nImages: size, totalCount: totalCount || 0, validCount: validCount || 0, meanVal: null };
      }
      if (!validCount || validCount === 0) {
        return { status: 'C2', dataset: chosen, nImages: size, totalCount, validCount: 0, meanVal: null };
      }

      const meanVal = await getInfo(
        meanImg.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: geom,
          scale: scale,
          maxPixels: 1e9
        }).get('chlor_a')
      );

      if (meanVal === null || meanVal === undefined || !Number.isFinite(meanVal) || meanVal <= 0 || meanVal > 1000) {
        return { status: 'C3', dataset: chosen, nImages: size, totalCount, validCount, meanVal };
      }

      return { status: 'OK', dataset: chosen, nImages: size, totalCount, validCount, meanVal };
    }

    // 2. Compute stats for both periods
    const s1 = await getPeriodStats(periods[0].start, periods[0].end);
    const s2 = await getPeriodStats(periods[1].start, periods[1].end);

    console.log('Geom: center (-45.4328, 140.4686), r=100km');

    // 3. Handle data issues (C1/C2/C3)
    if (s1.status === 'C1' || s2.status === 'C1') {
      console.log('At least one period has no images after fallbacks.');
      console.log('C1');
      return;
    }
    if (s1.status === 'C2' || s2.status === 'C2') {
      console.log('At least one period has 0 valid pixels after masking.');
      console.log('C2');
      return;
    }
    if (s1.status === 'C3' || s2.status === 'C3') {
      console.log('Invalid statistics (null/NaN/out-of-range).');
      console.log('C3');
      return;
    }

    const cov1 = (s1.validCount / s1.totalCount) * 100.0;
    const cov2 = (s2.validCount / s2.totalCount) * 100.0;

    console.log(`${periods[0].label}: Dataset=${s1.dataset}, Images=${s1.nImages}, Mean=${s1.meanVal.toFixed(3)} mg/m^3, ValidPix=${s1.validCount}/${s1.totalCount} (${cov1.toFixed(1)}%)`);
    console.log(`${periods[1].label}: Dataset=${s2.dataset}, Images=${s2.nImages}, Mean=${s2.meanVal.toFixed(3)} mg/m^3, ValidPix=${s2.validCount}/${s2.totalCount} (${cov2.toFixed(1)}%)`);

    const delta = s2.meanVal - s1.meanVal;
    console.log(`Delta=${delta.toFixed(3)} mg/m^3`);

    // 4. Final Answer
    if (delta > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
